window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-658849f4dfbf8487"]={"versions": [{"id": "FIG-658849f4dfbf8487", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR Classic Platform FlexRay Transport Protocols (<code>FrTp</code>). Das Diagramm illustriert den elementaren Protokollablauf einer unsegmentierten Punkt-zu-Punkt-Übertragung (1:1 Transfer) unter Verwendung einer Bestätigung (Acknowledgement) ohne Wiederholungsmechanismus (without Retry).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Sender</code>: Sender-Instanz des FlexRay Transport Layer.\n</li><li><code>Receiver</code>: Empfänger-Instanz des FlexRay Transport Layer.\n</li><li><code>SF</code>: Single Frame PDU (Protokolldateneinheit zur unsegmentierten Nutzdatenübertragung vom Sender zum Empfänger).\n</li><li><code>AF</code>: Acknowledgement Frame PDU (Quittungs-PDU zur Bestätigung des fehlerfreien Empfangs vom Empfänger an den Sender).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Sender</code> initiiert den Datentransfer durch das Aussenden eines unsegmentierten Datenrahmens (<code>SF</code>) an den <code>Receiver</code>.\n</li><li>Nach vollständigem und korrektem Empfang des <code>SF</code> generiert und sendet der <code>Receiver</code> einen Bestätigungsrahmen (<code>AF</code>) zurück an den <code>Sender</code>.\n</li><li>Mit dem Eintreffen des <code>AF</code> beim <code>Sender</code> ist der unsegmentierte Übertragungsvorgang erfolgreich abgeschlossen; es sind keine Wiederholungszyklen vorgesehen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm definiert den minimalen Erfolgsfall für quittierte Einzelframe-Übertragungen im AUTOSAR FlexRay Transport Protocol.\n</li><li>Entwickler müssen sicherstellen, dass auf Empfängerseite nach Erhalt eines SF die Generierung und Übertragung des AF innerhalb der spezifizierten Protokoll-Timeouts (z. B. As/Ar bzw. N_Ar/N_As) erfolgt.\n</li><li>Da kein Retry-Mechanismus („without Retry“) modelliert ist, führt das Ausbleiben oder ein fehlerhafter Empfang des AF zu einem Übertragungsfehlerabbruch im Sender ohne erneuten Sendeversuch des SF.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-943825aa843dc367", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des AUTOSAR Classic Platform FlexRay Transport Protocols (<code>FrTp</code>). Das Diagramm illustriert den elementaren Protokollablauf einer unsegmentierten Punkt-zu-Punkt-Übertragung (1:1 Transfer) unter Verwendung einer Bestätigung (Acknowledgement) ohne Wiederholungsmechanismus (without Retry).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Sender</code>: Sender-Instanz des FlexRay Transport Layer.\n</li><li><code>Receiver</code>: Empfänger-Instanz des FlexRay Transport Layer.\n</li><li><code>SF</code>: Single Frame PDU (Protokolldateneinheit zur unsegmentierten Nutzdatenübertragung vom Sender zum Empfänger).\n</li><li><code>AF</code>: Acknowledgement Frame PDU (Quittungs-PDU zur Bestätigung des fehlerfreien Empfangs vom Empfänger an den Sender).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Sender</code> initiiert den Datentransfer durch das Aussenden eines unsegmentierten Datenrahmens (<code>SF</code>) an den <code>Receiver</code>.\n</li><li>Nach vollständigem und korrektem Empfang des <code>SF</code> generiert und sendet der <code>Receiver</code> einen Bestätigungsrahmen (<code>AF</code>) zurück an den <code>Sender</code>.\n</li><li>Mit dem Eintreffen des <code>AF</code> beim <code>Sender</code> ist der unsegmentierte Übertragungsvorgang erfolgreich abgeschlossen; es sind keine Wiederholungszyklen vorgesehen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Diagramm definiert den minimalen Erfolgsfall für quittierte Einzelframe-Übertragungen im AUTOSAR FlexRay Transport Protocol.\n</li><li>Entwickler müssen sicherstellen, dass auf Empfängerseite nach Erhalt eines SF die Generierung und Übertragung des AF innerhalb der spezifizierten Protokoll-Timeouts (z. B. As/Ar bzw. N_Ar/N_As) erfolgt.\n</li><li>Da kein Retry-Mechanismus („without Retry“) modelliert ist, führt das Ausbleiben oder ein fehlerhafter Empfang des AF zu einem Übertragungsfehlerabbruch im Sender ohne erneuten Sendeversuch des SF.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-658849f4dfbf8487", "to": "FIG-943825aa843dc367", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
